from rest_framework import viewsets, permissions
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import FormSubmission
from .serializers import FormSubmissionSerializer

class FormSubmissionViewSet(viewsets.ModelViewSet):
    serializer_class = FormSubmissionSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return FormSubmission.objects.filter(form__organization=self.request.user.organization)

    @action(detail=False, methods=['get'])
    def filter_field_value(self, request):
        field_key = request.query_params.get('key')
        field_val = request.query_params.get('value')

        submissions = self.get_queryset().filter(payload__contains={field_key: field_val})
        page = self.paginate_queryset(submissions)
        if page is not None:
            serializer = self.get_serializer(page, many=True)
            return self.get_paginated_response(serializer.data)
        serializer = self.get_serializer(submissions, many=True)
        return Response(serializer.data)
